export const SUPPORTING_ADMIN_AREA_KEYS=Object.freeze(['users','reports','access','school','portal','diagnostics','imports','workflows'] as const);
export function isOperationalWorkspaceDefinition(definition:{system:boolean;workspaceKey:string}){return definition.system===false||(OPERATIONAL_WORKSPACE_KEYS as readonly string[]).includes(definition.workspaceKey)}

